#define BW_IOMUXC_GPR3_OCRAM_CTL(v)   (HW_IOMUXC_GPR3_WR((HW_IOMUXC_GPR3_RD() & ~BM_IOMUXC_GPR3_OCRAM_CTL) | BF_IOMUXC_GPR3_OCRAM_CTL(v)))
